"from bs4 import BeautifulSoup\n\nwith open(r'tests/workday/Systems Software Engineer - New College Grad 2026.htm', 'r', encoding='utf-8') as f:\n    soup = BeautifulSoup(f.read(), 'html.parser')\n\nprint(\"=== RESUME / FILE INPUT ===\")\nfile_input = soup.find('input', {'type': 'file'})\nif file_input:\n    print(\"File input:\", file_input)\n    print(\"Parent 3 levels:\")\n    p = file_input\n    for i in range(4):\n        p = p.parent if p else None\n        if p:\n            print(f\"Level {i+1}: <{p.name} data-automation-id='{p.get('data-automation-id')}' class='{p.get('class')}'>\")\n\nprint(\"\\n=== ALL FORM FIELDS ===\")\nfor d in soup.find_all(attrs={'data-automation-id': lambda x: x and 'formField' in str(x)}):\n    lbl = d.find('label').text if d.find('label') else 'NO LABEL'\n    inp = d.find(['input', 'select', 'textarea'])\n    inp_id = inp.get('id') if inp else None\n    inp_name = inp.get('name') if inp else None\n    inp_type = inp.get('type') if inp else None\n    inp_val = inp.get('value') if inp else None\n    print(f\"{d.get('data-automation-id')} | {lbl} | id={inp_id} | name={inp_name} | type={inp_type} | val={inp_val}\")\n\nprint(\"\\n=== ALL BUTTONS & SURROUNDING HEADINGS ===\")\nfor btn in soup.find_all('button'):\n    btn_text = btn.text.strip()\n    btn_auto = btn.get('data-automation-id')\n    # find closest heading or section\n    sec = btn.find_parent(attrs={'role': 'group'}) or btn.find_parent('div')\n    sec_heading = sec.find(['h2', 'h3', 'h4', 'h5']).text if sec and sec.find(['h2', 'h3', 'h4', 'h5']) else ''\n    print(f\"Button: '{btn_text}' (auto-id='{btn_auto}') in Section: '{sec_heading}'\")\n"